export const loomModelLabel = (model: string): string | undefined => {
  if (model === "loom") return "Loom";
  if (!model.startsWith("loom:")) return undefined;
  const variant = model.slice("loom:".length);
  return variant === "" ? "Loom" : `Loom (${variant})`;
};

