const LABELS: Record<string, string> = {
  "gpt-6.1-sol": "GPT-6.1 Sol",
  "claude-opus-5-5": "Opus 5.5",
};

export const formatModelLabel = (model: string): string => {
  const id = model.trim();
  return LABELS[id] ?? id;
};

